ALTER TABLE documents ADD COLUMN finalized_at DATETIME(3) NULL, ADD COLUMN finalized_by VARCHAR(191) NULL, ADD COLUMN final_snapshot JSON NULL;
UPDATE documents SET status='Disetujui Bapperida' WHERE status='Disetujui';
CREATE TABLE document_status_logs (id VARCHAR(191) NOT NULL, document_id VARCHAR(191) NOT NULL, dari VARCHAR(50) NULL, ke VARCHAR(50) NOT NULL, oleh VARCHAR(191) NOT NULL, alasan TEXT NULL, perubahan JSON NULL, waktu DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX document_status_logs_document_id_waktu_idx(document_id,waktu), PRIMARY KEY(id), CONSTRAINT document_status_logs_document_id_fkey FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE evaluasi_triwulan (id VARCHAR(191) NOT NULL, jenis VARCHAR(20) NOT NULL, opd_id VARCHAR(100) NULL, tahun VARCHAR(4) NOT NULL, triwulan INTEGER NOT NULL, judul VARCHAR(255) NULL, catatan TEXT NULL, file_path VARCHAR(500) NOT NULL, nama_file_asli VARCHAR(255) NOT NULL, mime VARCHAR(100) NOT NULL, ukuran INTEGER NOT NULL, versi INTEGER NOT NULL, aktif BOOLEAN NOT NULL DEFAULT true, diunggah_oleh VARCHAR(191) NOT NULL, diunggah_pada DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX evaluasi_triwulan_scope_idx(jenis,opd_id,tahun,triwulan,aktif), PRIMARY KEY(id));
